contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmt, uint minSum, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // Ensure we have enough ether to forward.
        require(address(this).balance >= depositAmt);

        // Set up: initialize and set min sum.
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Record before values.
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;

        // Deposit.
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // Attempt to collect.
        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after values.
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;

        // General rule: If collect succeeded and reduced the caller's balance by collectAmt,
        // then the ether held by c also decreased by exactly collectAmt.
        assert(reverted || balAfter != balBefore - collectAmt || cBalanceAfter == cBalanceBefore - collectAmt);
    }

    receive() external payable {}
}

